function encryptPayload(plaintext, tenantId, kmsClient) {
  const DEK = kmsClient.getDataKey(tenantId);
  const wrappedDEK = kmsClient.wrapKey(DEK, tenantId);
  const ciphertext = cryptoAesGCM(nonce, DEK, plaintext);
